import { Component, computed, inject, input, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { EMPTY, distinctUntilChanged, skip, switchMap } from 'rxjs';
import { PersonView } from '../../core/people';
import { PoolMemberView, Pools, SHARE_PATTERN } from '../../core/pools';
import { Sheets } from '../../core/sheet';

type MemberForm = FormGroup<{
  personId: FormControl<string>;
  share: FormControl<string>;
  from: FormControl<string>;
  to: FormControl<string>;
}>;

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's pools: each has members chosen from the sheet's people and its other pools, with a share percent of it.
@Component({
  selector: 'app-pools',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="pools-heading">
      <h3 id="pools-heading">Pools</h3>
      <ul aria-label="Pools">
        @for (pool of pools.all(); track pool.id) {
          <li [attr.data-testid]="'pool-row-' + pool.name">
            <span data-testid="pool-name">{{ pool.name }}</span>:
            total share <span data-testid="pool-total-share">{{ pool.totalShare }}</span>,
            balanced <span data-testid="pool-balanced">{{ pool.balanced ? 'yes' : 'no' }}</span>
            <ul [attr.aria-label]="'Members of ' + pool.name">
              @for (m of pool.members; track memberKey(m)) {
                <li [attr.data-testid]="'pool-member-' + pool.name + '-' + memberKey(m)">
                  <span data-testid="pool-member-name">{{ m.name }}</span>:
                  <span data-testid="pool-share">{{ m.share }}</span>,
                  cut <span data-testid="pool-cut">{{ m.cut ?? '' }}</span>
                  @if (m.from || m.to) { (from {{ m.from ?? 'any day' }} to {{ m.to ?? 'any day' }}) }
                  @if (m.retired) { (retired) }
                </li>
              }
            </ul>
            <form [formGroup]="memberForm(pool.id)" (ngSubmit)="addMember(pool.id)"
                  [attr.aria-label]="'Add a member to ' + pool.name">
              <label [attr.for]="'pool-member-select-' + pool.id">Member</label>
              <select [id]="'pool-member-select-' + pool.id" data-testid="pool-member-select" formControlName="personId">
                <option value="">Choose a person or a pool</option>
                @for (p of people(); track p.id) {
                  <option [value]="p.id">{{ p.name }}</option>
                }
                @for (other of pools.all(); track other.id) {
                  <option [value]="'pool:' + other.id">pool:{{ other.name }}</option>
                }
              </select>
              <label [attr.for]="'pool-member-share-' + pool.id">Share %</label>
              <input [id]="'pool-member-share-' + pool.id" data-testid="pool-member-share" formControlName="share"
                     inputmode="decimal" autocomplete="off" />
              <label [attr.for]="'pool-member-from-' + pool.id">From (blank: no start)</label>
              <input [id]="'pool-member-from-' + pool.id" type="date" data-testid="pool-member-from"
                     formControlName="from" />
              <label [attr.for]="'pool-member-to-' + pool.id">To (blank: no end)</label>
              <input [id]="'pool-member-to-' + pool.id" type="date" data-testid="pool-member-to" formControlName="to" />
              <button type="submit" data-testid="pool-member-add" [disabled]="busy().has(pool.id)">Add member</button>
              @if (errors().get(pool.id); as err) {
                <p role="alert" data-testid="pool-error">{{ err }}</p>
              }
            </form>
          </li>
        }
      </ul>

      <form [formGroup]="form" (ngSubmit)="add()" aria-label="Add a pool">
        <label for="pool-form-name">Name</label>
        <input id="pool-form-name" data-testid="pool-form-name" formControlName="name" autocomplete="off" />
        <button type="submit" data-testid="pool-form-submit" [disabled]="saving()">Add pool</button>
        @if (error(); as err) {
          <p role="alert" data-testid="pool-form-error">{{ err }}</p>
        }
      </form>
    </section>
  `,
})
export class PoolsPanel {
  /** The sheet's people, the members are chosen from. */
  readonly people = input.required<PersonView[]>();

  protected readonly pools = inject(Pools);
  private readonly sheets = inject(Sheets);

  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** Each pool's error, by pool id. */
  protected readonly errors = signal<ReadonlyMap<number, string>>(new Map());
  /** The pools a member is being added to. */
  protected readonly busy = signal<ReadonlySet<number>>(new Set());
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
  });
  private readonly memberForms = new Map<number, MemberForm>();

  constructor() {
    // Each (re)load of a sheet re-reads its pools from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          this.errors.set(new Map());
          this.memberForms.clear();
          return this.pools.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the pools.') });
    // A change of the sheet's pot re-reads the pools, with their cuts of it.
    toObservable(computed(() => {
      const sheet = this.sheets.current();
      return sheet ? `${sheet.id}\n${sheet.pot ?? ''}` : null;
    }))
      .pipe(
        distinctUntilChanged(),
        skip(1),
        switchMap(() => {
          const sheet = this.sheets.current();
          return sheet && sheet.id === this.sheets.loaded()?.id ? this.pools.load(sheet.id) ?? EMPTY : EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the pools.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  /** A member's key in its row's test id: the person's id, or pool-<name> for a pool. */
  protected memberKey(m: PoolMemberView): string {
    return m.memberPoolId !== null ? `pool-${m.name}` : String(m.personId);
  }

  /** The pool row's form to add a member, made the first time the row shows. */
  protected memberForm(poolId: number): MemberForm {
    let form = this.memberForms.get(poolId);
    if (!form) {
      const made: MemberForm = new FormGroup({
        personId: new FormControl('', { nonNullable: true }),
        share: new FormControl('', { nonNullable: true }),
        from: new FormControl('', { nonNullable: true }),
        to: new FormControl('', { nonNullable: true }),
      });
      made.valueChanges.subscribe(() => this.setError(poolId, null));
      this.memberForms.set(poolId, made);
      form = made;
    }
    return form;
  }

  protected add(): void {
    // A second submit before the first has answered is ignored, so it records one pool.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const name = this.form.controls.name.value.trim();
    if (name === '') {
      this.error.set('Type the pool\'s name.');
      return;
    }
    this.saving.set(true);
    this.pools.add(sheet.id, name).subscribe({
      next: () => {
        this.saving.set(false);
        this.form.reset({ name: '' }, { emitEvent: false });
      },
      error: () => {
        this.saving.set(false);
        this.error.set('Could not add that pool: is it already on the sheet?');
      },
    });
  }

  protected addMember(poolId: number): void {
    if (this.busy().has(poolId)) return;
    this.setError(poolId, null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const value = this.memberForm(poolId).getRawValue();
    const share = value.share.trim();
    if (value.personId === '') {
      this.setError(poolId, 'Choose a person or a pool to add.');
      return;
    }
    if (!SHARE_PATTERN.test(share) || Number(share) <= 0 || Number(share) > 100) {
      this.setError(poolId, 'Type a share more than 0.00 and at most 100.00, with up to two decimals.');
      return;
    }
    const from = value.from.trim();
    const to = value.to.trim();
    if ((from !== '' && !DATE_PATTERN.test(from)) || (to !== '' && !DATE_PATTERN.test(to))) {
      this.setError(poolId, 'Type the dates as yyyy-mm-dd, or leave them blank.');
      return;
    }
    if (from !== '' && to !== '' && to < from) {
      this.setError(poolId, 'The to-date cannot be before the from-date.');
      return;
    }
    this.busy.update((s) => new Set(s).add(poolId));
    const done = () => this.busy.update((s) => {
      const next = new Set(s);
      next.delete(poolId);
      return next;
    });
    const member = value.personId.startsWith('pool:')
      ? { memberPoolId: Number(value.personId.slice('pool:'.length)) }
      : { personId: Number(value.personId) };
    this.pools.addMember(sheet.id, poolId, member, share, from || null, to || null).subscribe({
      next: () => {
        done();
        this.memberForm(poolId).reset({ personId: '', share: '', from: '', to: '' }, { emitEvent: false });
      },
      error: () => {
        done();
        this.setError(poolId, 'Could not add that member: is it already in a pool, is the to-date before the from-date, would the pool contain itself, or would the chain of pools be over three deep?');
      },
    });
  }

  private setError(poolId: number, message: string | null): void {
    this.errors.update((m) => {
      const next = new Map(m);
      if (message === null) next.delete(poolId);
      else next.set(poolId, message);
      return next;
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, switchMap, tap } from 'rxjs';

/** A share percent the pool's row accepts: up to two decimals (more than 0.00 and at most 100.00 is checked apart). */
export const SHARE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** A member of a pool: a person of the sheet, or another pool of it, with its share percent. */
export interface PoolMemberView {
  /** The person that is the member; null when the member is a pool. */
  personId: number | null;
  /** The pool that is the member; null when the member is a person. */
  memberPoolId: number | null;
  /** The person's name, or the member pool's. */
  name: string;
  share: string;
  /** Retired as soon as a retirement date is set: their share still counts toward the total, but they have a cut
   *  of 0.00 and the others' cuts take up theirs; a pool whose every member is retired has no cuts. */
  retired: boolean;
  /** The first and last day the membership is in force (yyyy-mm-dd); null: no start, no end. Outside them, on the
   *  sheet's today, the member is left out of the pool's total share and has no cut. */
  from: string | null;
  to: string | null;
  /** Their cut of the pool's pot (two decimals); null when the pool has no pot or is not balanced, or the member's
   *  dates do not include the sheet's today. A pool that is a
   *  member of another has its cut there as its pot; one that is a member of none has the sheet's. */
  cut: string | null;
}

/** A pool on the sheet: its members, their total share, and balanced when that is exactly 100.00. */
export interface PoolView {
  id: number;
  name: string;
  members: PoolMemberView[];
  totalShare: string;
  balanced: boolean;
}

// The pools on the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly list = signal<PoolView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's pools from the store; null clears them. */
  load(sheetId: string | null): Observable<PoolView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<PoolView[]>(this.base(sheetId)).pipe(tap((list) => this.list.set(list)));
  }

  /** Add a pool; refused when the name is blank or already a pool on the sheet. */
  add(sheetId: string, name: string): Observable<PoolView> {
    return this.http.post<PoolView>(this.base(sheetId), { name }).pipe(
      tap((added) => this.list.update((list) => [...list, added])),
    );
  }

  /** Add a person or another pool to a pool with a share; refused when the person is already in it, the share is
   *  out of range, the to-date is before the from-date, or the pool member is already in a pool, would contain itself
   *  or make a chain over three deep. The from-date and to-date are optional (null).
   *  Every pool is re-read after, since a pool's pot follows its cut in the pool above. */
  addMember(sheetId: string, poolId: number, member: { personId: number } | { memberPoolId: number },
            share: string, from: string | null, to: string | null): Observable<PoolView[]> {
    return this.http.post<PoolView>(`${this.base(sheetId)}/${poolId}/members`, { ...member, share, from, to }).pipe(
      switchMap(() => this.http.get<PoolView[]>(this.base(sheetId))),
      tap((list) => this.list.set(list)),
    );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }
}
package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.IntStream;
import net.officefloor.hq.app.history.SheetHistory;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The pools on a sheet. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/pools")
public class PoolController {

    /** A member as the pool's row shows it: a person (personId) or another pool (memberPoolId, its name as the
     *  name), with the membership's from-date and to-date (null: none); cut is its cut of the pool's pot, null when
     *  the pool shows none or the membership's dates do not include the sheet's today. */
    public record MemberView(Long personId, Long memberPoolId, String name, String share, boolean retired,
            String cut, LocalDate from, LocalDate to) {

        public static MemberView of(PoolService.Member m, BigDecimal cut) {
            String shown = cut == null || !m.inForce() ? null : cut.toPlainString();
            if (m.pool() != null) {
                return new MemberView(null, m.pool().getId(), m.pool().getName(), m.share().toPlainString(), false,
                        shown, m.from(), m.to());
            }
            return new MemberView(m.person().getId(), null, m.person().getName(), m.share().toPlainString(),
                    m.person().isRetired(), shown, m.from(), m.to());
        }
    }

    /** A pool as the screen shows it: its members, their total share and whether that is exactly 100.00. */
    public record PoolView(long id, String name, List<MemberView> members, String totalShare, boolean balanced) {

        public static PoolView of(PoolService.PoolWithMembers p) {
            List<BigDecimal> cuts = p.cuts();
            return new PoolView(p.pool().getId(), p.pool().getName(),
                    IntStream.range(0, p.members().size())
                            .mapToObj(i -> MemberView.of(p.members().get(i), cuts == null ? null : cuts.get(i))).toList(),
                    p.totalShare().toPlainString(), p.balanced());
        }
    }

    /** A pool as the form submits it. */
    public record PoolForm(@NotNull @Size(max = 200) String name) {
    }

    /** A member as the pool's row submits it: a person or another pool of the sheet, exactly one given, with the
     *  membership's optional from-date and to-date. */
    public record MemberForm(Long personId, Long memberPoolId, @NotNull BigDecimal share, LocalDate from,
            LocalDate to) {
    }

    private final PoolService pools;

    public PoolController(PoolService pools) {
        this.pools = pools;
    }

    @GetMapping
    public List<PoolView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        // A sheet shown as of a date reads its pools with that date standing in for its today.
        return pools.list(sheetId, asOf).stream().map(PoolView::of).toList();
    }

    @PostMapping
    public PoolView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PoolForm request) {
        return PoolView.of(new PoolService.PoolWithMembers(pools.add(sheetId, user, request.name()), List.of(), null));
    }

    @PostMapping("/{poolId}/members")
    public PoolView addMember(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long poolId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MemberForm request) {
        return PoolView.of(pools.addMember(sheetId, user, poolId, request.personId(), request.memberPoolId(),
                request.share(), request.from(), request.to()));
    }
}
