export class PoolsPanel {
  /** The sheet's people, the members are chosen from. */
  readonly people = input.required<PersonView[]>();

  protected readonly pools = inject(Pools);
  private readonly sheets = inject(Sheets);

  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** Each pool's error, by pool id. */
  protected readonly errors = signal<ReadonlyMap<number, string>>(new Map());
  /** The pools a member is being added to. */
  protected readonly busy = signal<ReadonlySet<number>>(new Set());
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
  });
  private readonly memberForms = new Map<number, MemberForm>();

  constructor() {
    // Each (re)load of a sheet re-reads its pools from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          this.errors.set(new Map());
          this.memberForms.clear();
          return this.pools.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the pools.') });
    // A change of the sheet's pot re-reads the pools, with their cuts of it.
    toObservable(computed(() => {
      const sheet = this.sheets.current();
      return sheet ? `${sheet.id}\n${sheet.pot ?? ''}` : null;
    }))
      .pipe(
        distinctUntilChanged(),
        skip(1),
        switchMap(() => {
          const sheet = this.sheets.current();
          return sheet && sheet.id === this.sheets.loaded()?.id ? this.pools.load(sheet.id) ?? EMPTY : EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the pools.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  /** A member's key in its row's test id: the person's id, or pool-<name> for a pool. */
  protected memberKey(m: PoolMemberView): string {
    return m.memberPoolId !== null ? `pool-${m.name}` : String(m.personId);
  }

  /** The pool row's form to add a member, made the first time the row shows. */
  protected memberForm(poolId: number): MemberForm {
    let form = this.memberForms.get(poolId);
    if (!form) {
      const made: MemberForm = new FormGroup({
        personId: new FormControl('', { nonNullable: true }),
        share: new FormControl('', { nonNullable: true }),
        from: new FormControl('', { nonNullable: true }),
        to: new FormControl('', { nonNullable: true }),
      });
      made.valueChanges.subscribe(() => this.setError(poolId, null));
      this.memberForms.set(poolId, made);
      form = made;
    }
    return form;
  }

  protected add(): void {
    // A second submit before the first has answered is ignored, so it records one pool.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const name = this.form.controls.name.value.trim();
    if (name === '') {
      this.error.set('Type the pool\'s name.');
      return;
    }
    this.saving.set(true);
    this.pools.add(sheet.id, name).subscribe({
      next: () => {
        this.saving.set(false);
        this.form.reset({ name: '' }, { emitEvent: false });
      },
      error: () => {
        this.saving.set(false);
        this.error.set('Could not add that pool: is it already on the sheet?');
      },
    });
  }

  protected addMember(poolId: number): void {
    if (this.busy().has(poolId)) return;
    this.setError(poolId, null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const value = this.memberForm(poolId).getRawValue();
    const share = value.share.trim();
    if (value.personId === '') {
      this.setError(poolId, 'Choose a person or a pool to add.');
      return;
    }
    if (!SHARE_PATTERN.test(share) || Number(share) <= 0 || Number(share) > 100) {
      this.setError(poolId, 'Type a share more than 0.00 and at most 100.00, with up to two decimals.');
      return;
    }
    const from = value.from.trim();
    const to = value.to.trim();
    if ((from !== '' && !DATE_PATTERN.test(from)) || (to !== '' && !DATE_PATTERN.test(to))) {
      this.setError(poolId, 'Type the dates as yyyy-mm-dd, or leave them blank.');
      return;
    }
    if (from !== '' && to !== '' && to < from) {
      this.setError(poolId, 'The to-date cannot be before the from-date.');
      return;
    }
    this.busy.update((s) => new Set(s).add(poolId));
    const done = () => this.busy.update((s) => {
      const next = new Set(s);
      next.delete(poolId);
      return next;
    });
    const member = value.personId.startsWith('pool:')
      ? { memberPoolId: Number(value.personId.slice('pool:'.length)) }
      : { personId: Number(value.personId) };
    this.pools.addMember(sheet.id, poolId, member, share, from || null, to || null).subscribe({
      next: () => {
        done();
        this.memberForm(poolId).reset({ personId: '', share: '', from: '', to: '' }, { emitEvent: false });
      },
      error: () => {
        done();
        this.setError(poolId, 'Could not add that member: is it already in a pool, is the to-date before the from-date, would the pool contain itself, or would the chain of pools be over three deep?');
      },
    });
  }

  private setError(poolId: number, message: string | null): void {
    this.errors.update((m) => {
      const next = new Map(m);
      if (message === null) next.delete(poolId);
      else next.set(poolId, message);
      return next;
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, switchMap, tap } from 'rxjs';

/** A share percent the pool's row accepts: up to two decimals (more than 0.00 and at most 100.00 is checked apart). */
export const SHARE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** A member of a pool: a person of the sheet, or another pool of it, with its share percent. */
export interface PoolMemberView {
  /** The person that is the member; null when the member is a pool. */
  personId: number | null;
  /** The pool that is the member; null when the member is a person. */
  memberPoolId: number | null;
  /** The person's name, or the member pool's. */
  name: string;
  share: string;
  /** Retired as soon as a retirement date is set: their share still counts toward the total, but they have a cut
   *  of 0.00 and the others' cuts take up theirs; a pool whose every member is retired has no cuts. */
  retired: boolean;
  /** The first and last day the membership is in force (yyyy-mm-dd); null: no start, no end. Outside them, on the
   *  sheet's today, the member is left out of the pool's total share and has no cut. */
  from: string | null;
  to: string | null;
  /** Their cut of the pool's pot (two decimals); null when the pool has no pot or is not balanced, or the member's
   *  dates do not include the sheet's today. A pool that is a
   *  member of another has its cut there as its pot; one that is a member of none has the sheet's. */
  cut: string | null;
}

/** A pool on the sheet: its members, their total share, and balanced when that is exactly 100.00. */
export interface PoolView {
  id: number;
  name: string;
  members: PoolMemberView[];
  totalShare: string;
  balanced: boolean;
}

// The pools on the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly list = signal<PoolView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's pools from the store; null clears them. */
  load(sheetId: string | null): Observable<PoolView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<PoolView[]>(this.base(sheetId)).pipe(tap((list) => this.list.set(list)));
  }

  /** Add a pool; refused when the name is blank or already a pool on the sheet. */
  add(sheetId: string, name: string): Observable<PoolView> {
    return this.http.post<PoolView>(this.base(sheetId), { name }).pipe(
      tap((added) => this.list.update((list) => [...list, added])),
    );
  }

  /** Add a person or another pool to a pool with a share; refused when the person is already in it, the share is
   *  out of range, the to-date is before the from-date, or the pool member is already in a pool, would contain itself
   *  or make a chain over three deep. The from-date and to-date are optional (null).
   *  Every pool is re-read after, since a pool's pot follows its cut in the pool above. */
  addMember(sheetId: string, poolId: number, member: { personId: number } | { memberPoolId: number },
            share: string, from: string | null, to: string | null): Observable<PoolView[]> {
    return this.http.post<PoolView>(`${this.base(sheetId)}/${poolId}/members`, { ...member, share, from, to }).pipe(
      switchMap(() => this.http.get<PoolView[]>(this.base(sheetId))),
      tap((list) => this.list.set(list)),
    );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }
}
